document.head.insertAdjacentHTML('beforeend','<link rel="stylesheet" href="firebase-integration.css">');

const firebaseConfig={apiKey:'AIzaSyAVY8UdZ9TQe_6b5lF-qK7SB_t4hHtdN48',authDomain:'rifqah-17df3.firebaseapp.com',projectId:'rifqah-17df3',storageBucket:'rifqah-17df3.firebasestorage.app',messagingSenderId:'343149909372',appId:'1:343149909372:web:e0bca444500713b81580f9'};
firebase.initializeApp(firebaseConfig);
const auth=firebase.auth(),db=firebase.firestore(),stamp=firebase.firestore.FieldValue.serverTimestamp;
const ADMIN_EMAIL='hmdfhd7811@gmail.com';
let currentUser=null,currentProfile=null,signupMode=false,scannerStream=null,scanTimer=null;
statusMap.picked=['approved','تم الاستلام'];statusMap.late=['rejected','متأخر'];

document.body.insertAdjacentHTML('beforeend','<span class="cloud-state" id="cloudState">جاري الاتصال بقاعدة البيانات…</span>');
const fbError=e=>({
  'auth/email-already-in-use':'البريد مستخدم مسبقًا','auth/invalid-credential':'البريد أو كلمة المرور غير صحيحة',
  'auth/weak-password':'كلمة المرور ضعيفة','auth/invalid-email':'البريد الإلكتروني غير صحيح',
  'permission-denied':'ليس لديك صلاحية لتنفيذ هذا الإجراء'
}[e?.code]||e?.message||'تعذر تنفيذ العملية');

function openAuth(){if(currentUser){if(confirm('هل تريد تسجيل الخروج؟'))auth.signOut();return}openOverlay('authModal')}
function toggleAuthMode(){signupMode=!signupMode;signupFields.classList.toggle('hidden',!signupMode);authTitle.textContent=signupMode?'إنشاء حساب جديد':'تسجيل الدخول';authSubmit.textContent=signupMode?'إنشاء الحساب':'دخول';authSwitch.textContent=signupMode?'لديك حساب؟ تسجيل الدخول':'ليس لديك حساب؟ إنشاء حساب';authPassword.autocomplete=signupMode?'new-password':'current-password'}
async function handleAuth(e){e.preventDefault();try{authSubmit.disabled=true;if(signupMode){let name=authName.value.trim(),phone=authPhone.value.trim();if(name.split(/\s+/).length<2)throw new Error('اكتب الاسم الثنائي');if(!/^05\d{8}$/.test(phone))throw new Error('رقم الجوال يجب أن يبدأ بـ 05 ويتكون من 10 أرقام');let c=await auth.createUserWithEmailAndPassword(authEmail.value.trim(),authPassword.value);await c.user.updateProfile({displayName:name});await db.collection('lab_profiles').doc(c.user.uid).set({fullName:name,email:c.user.email,phone,role:'borrower',createdAt:stamp()});await c.user.sendEmailVerification();toast('أرسلنا رابط تفعيل إلى بريدك الإلكتروني')}else await auth.signInWithEmailAndPassword(authEmail.value.trim(),authPassword.value);closeOverlay('authModal');authForm.reset()}catch(x){toast(fbError(x))}finally{authSubmit.disabled=false}}

auth.onAuthStateChanged(async user=>{currentUser=user;currentProfile=null;if(user){let ref=db.collection('lab_profiles').doc(user.uid),snap=await ref.get();if(!snap.exists){await ref.set({fullName:user.displayName||user.email.split('@')[0],email:user.email,phone:'',role:'borrower',createdAt:stamp()})}currentProfile=(await ref.get()).data();let admin=user.emailVerified&&user.email.toLowerCase()===ADMIN_EMAIL;if(admin)currentProfile.role='admin';accountBtn.textContent='تسجيل الخروج';userAvatar.textContent=(currentProfile.fullName||user.email).trim()[0];document.querySelector('.hero span').textContent=`مرحباً، ${currentProfile.fullName||user.email} 👋`;roleBtn.classList.toggle('hidden',!admin);scanBtn.classList.toggle('hidden',!admin);await loadCloudData();if(admin)await seedInventory()}else{accountBtn.textContent='تسجيل الدخول';userAvatar.textContent='؟';roleBtn.classList.add('hidden');scanBtn.classList.add('hidden');orders=[];renderOrders()}cloudState.textContent=user?(user.emailVerified?'متصل بقاعدة البيانات':'فعّل بريدك لإرسال الطلبات'):'سجّل الدخول لإرسال الطلبات';refreshIcons()});

async function seedInventory(){let c=await db.collection('lab_inventory').limit(1).get();if(!c.empty)return;let batch=db.batch();inventory.forEach(i=>batch.set(db.collection('lab_inventory').doc(i.id),{...i,createdAt:stamp()}));await batch.commit();toast('تم تجهيز مخزون المعمل على Firebase')}
async function loadCloudData(){let inv=await db.collection('lab_inventory').where('active','==',true).get();if(!inv.empty){inventory=inv.docs.map(d=>({...d.data(),id:d.id}));renderHome();renderCatalog()}let q=currentProfile.role==='admin'?db.collection('lab_orders').orderBy('createdAt','desc'):db.collection('lab_orders').where('userId','==',currentUser.uid);let s=await q.get();orders=s.docs.map(d=>{let x=d.data();return{...x,id:d.id,orderItems:x.items,items:(x.items||[]).map(i=>i.name),date:x.createdAt?.toDate?.().toLocaleString('ar-SA')||'الآن',pickup:x.pickupAt?.toDate?.().toLocaleString('ar-SA'),returnAt:x.returnAt?.toDate?.().toLocaleString('ar-SA')}});renderOrders();if(currentProfile.role==='admin'){renderAdmin();renderRequests()}}

window.submitBooking=async function(){if(!currentUser)return openAuth();if(!currentUser.emailVerified)return toast('فعّل بريدك الإلكتروني أولًا ثم سجّل الدخول مجددًا');if(!terms.checked)return toast('وافق على شروط الاستخدام أولاً');let start=new Date(pickup.value),end=new Date(returnAt.value);if(!start.getTime()||!end.getTime()||end<=start)return toast('تحقق من مواعيد الاستلام والإرجاع');try{let ref=db.collection('lab_orders').doc(),code='TWQ-'+ref.id.slice(0,8).toUpperCase(),rows=cart.map(c=>{let i=inventory.find(x=>x.id===c.id);return{id:i.id,name:i.name,qty:c.qty}});await ref.set({code,userId:currentUser.uid,userName:currentProfile.fullName,userEmail:currentUser.email,userPhone:currentProfile.phone,items:rows,status:'pending',pickupAt:firebase.firestore.Timestamp.fromDate(start),returnAt:firebase.firestore.Timestamp.fromDate(end),purpose:purpose.value,notes:notes.value.trim().slice(0,500),createdAt:stamp(),updatedAt:stamp()});cart=[];save();updateCart();closeOverlay('cart');await loadCloudData();go('orders');toast('تم إرسال الطلب للمشرف')}catch(e){toast(fbError(e))}}

window.approveOrder=async id=>{try{let doc=orders.find(o=>o.id===id);await db.collection('lab_orders').doc(id).update({status:'approved',qrToken:crypto.randomUUID(),approvedAt:stamp(),updatedAt:stamp()});await loadCloudData();toast(`تم اعتماد الطلب ${doc?.code||''}`)}catch(e){toast(fbError(e))}};
window.rejectOrder=async id=>{try{await db.collection('lab_orders').doc(id).update({status:'rejected',updatedAt:stamp()});await loadCloudData();toast('تم رفض الطلب')}catch(e){toast(fbError(e))}};

const oldOpenOrder=window.openOrder||openOrder;window.openOrder=function(id){oldOpenOrder(id);let o=orders.find(x=>x.id===id);if(o&&['approved','picked'].includes(o.status)){setTimeout(()=>{let box=document.querySelector('#orderDetail .qrbox');if(!box)return;box.insertAdjacentHTML('afterend','<canvas id="orderQr" class="qr-canvas"></canvas>');QRCode.toCanvas(document.getElementById('orderQr'),JSON.stringify({orderId:o.id,token:o.qrToken||''}),{width:210,margin:1})},30)}};

async function openScanner(){openOverlay('scannerModal');scanResult.innerHTML='';if(!('BarcodeDetector'in window)){toast('استخدم الإدخال اليدوي في هذا المتصفح');return}try{scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});scannerVideo.srcObject=scannerStream;await scannerVideo.play();let detector=new BarcodeDetector({formats:['qr_code']});scanTimer=setInterval(async()=>{try{let codes=await detector.detect(scannerVideo);if(codes[0]){let p=JSON.parse(codes[0].rawValue);clearInterval(scanTimer);await showScannedOrder(p.orderId,p.token)}}catch{}},700)}catch{toast('تعذر فتح الكاميرا؛ استخدم الإدخال اليدوي')}}
function closeScanner(){if(scanTimer)clearInterval(scanTimer);scannerStream?.getTracks().forEach(t=>t.stop());scannerStream=null;closeOverlay('scannerModal')}
async function lookupOrderCode(){let s=await db.collection('lab_orders').where('code','==',manualCode.value.trim().toUpperCase()).limit(1).get();if(s.empty)return toast('لم يتم العثور على الطلب');await showScannedOrder(s.docs[0].id,s.docs[0].data().qrToken)}
async function showScannedOrder(id,token){let s=await db.collection('lab_orders').doc(id).get();if(!s.exists||s.data().qrToken!==token)return toast('رمز الطلب غير صالح');let o=s.data(),p=x=>x?.toDate?.().toLocaleString('ar-SA')||'—';scanResult.innerHTML=`<div class="scanresult"><h3>${o.userName}</h3><div class="meta">${o.code} · ${o.userPhone||o.userEmail}</div><p><b>القطع:</b> ${o.items.map(i=>`${i.name} × ${i.qty}`).join('، ')}</p><p><b>الاستلام:</b> ${p(o.pickupAt)}<br><b>الإرجاع:</b> ${p(o.returnAt)}</p><div class="actions"><button class="btn primary" onclick="recordHandover('${id}','pickup')">جاي يستلم</button><button class="btn secondary" onclick="recordHandover('${id}','return')">جاي يرجع</button></div></div>`}
async function recordHandover(id,action){try{await db.runTransaction(async t=>{let r=db.collection('lab_orders').doc(id),s=await t.get(r),o=s.data();if(action==='pickup'&&o.status!=='approved')throw new Error('الطلب ليس جاهزًا للاستلام');if(action==='return'&&o.status!=='picked')throw new Error('الطلب غير مسجل كمستلم');t.update(r,{status:action==='pickup'?'picked':'returned',[action==='pickup'?'pickedAt':'returnedAt']:stamp(),updatedAt:stamp()})});await showScannedOrder(id,(await db.collection('lab_orders').doc(id).get()).data().qrToken);await loadCloudData();toast(action==='pickup'?'تم تسجيل الاستلام':'تم تسجيل الإرجاع')}catch(e){toast(fbError(e))}}
